import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();

        double[] p = new double[20];
        double[] res = new double[1 << 20];
        double[] q = new double[20];

        for (int i = 0; i < n; i++) {
            p[i] = sc.nextDouble();
        }

        for (int i = 0; i < n; i++) {
            res[1 << i] = p[i];
        }

        for (int i = 0; i < n; i++) {
            q[i] = 0;
        }

        for (int i = 1; i < (1 << n); i++) {
            // Collect indices for v and w
            int[] vIndices = new int[n];
            int[] wIndices = new int[n];
            int vCount = 0, wCount = 0;
            double sum = 0.0;

            for (int j = 0; j < n; j++) {
                if (((i >> j) & 1) == 1) {
                    vIndices[vCount++] = j;
                } else {
                    wIndices[wCount++] = j;
                    sum += p[j];
                }
            }

            if (vCount == m || (vCount < m && sum < 1e-5)) {
                for (int x = 0; x < vCount; x++) {
                    q[vIndices[x]] += res[i];
                }
            } else if (vCount < m) {
                for (int x = 0; x < wCount; x++) {
                    int idx = wIndices[x];
                    res[i | (1 << idx)] += res[i] * p[idx] / sum;
                }
            }
        }

        for (int i = 0; i < n; i++) {
            System.out.printf("%.15f ", q[i]);
        }
        System.out.println();
        sc.close();
    }
}
